package com.example.lendlyapp
sealed class Screen(val route: String) { object Splash : Screen("splash") object Login : Screen("login") object Onboarding : Screen("onboarding") object Home : Screen("home") object History : Screen("history") object TransactionDetail : Screen("transaction_detail")
// Flujo de Cash In object CashInOptions : Screen("cash_in_options") object OnlineCashIn : Screen("online_cash_in") object OverTheCounter : Screen("over_the_counter") object CashInAmount : Screen("cash_in_amount") object TransactionSuccess : Screen("transaction_success")
// Notificaciones object Notifications : Screen("notifications") object Manage : Screen("manage") object CreditScore : Screen("credit_score") object Shop : Screen("shop") object Search : Screen("search")
// Verificación object VerifyPhone : Screen("verify_phone") object SmsVerification : Screen("sms_verification") object FaceRecognition : Screen("face_recognition") object IdVerification : Screen("id_verification") object VerifiedSuccess : Screen("verified_success") object ProfileDetail : Screen("profile_detail") object Signature : Screen("signature") object CreatePassword : Screen("create_password") object RegistrationDone : Screen("registration_done") object ProfileDetails : Screen("profile_details") }

package com.example.lendlyapp
sealed class Screen(val route: String) { object Splash : Screen("splash") object Login : Screen("login") object Onboarding : Screen("onboarding") object Home : Screen("home") object History : Screen("history") object TransactionDetail : Screen("transaction_detail")
// Flujo de Cash In object CashInOptions : Screen("cash_in_options") object OnlineCashIn : Screen("online_cash_in") object OverTheCounter : Screen("over_the_counter") object CashInAmount : Screen("cash_in_amount") object TransactionSuccess : Screen("transaction_success")
// Notificaciones object Notifications : Screen("notifications") object Manage : Screen("manage") object CreditScore : Screen("credit_score") object Shop : Screen("shop") object Search : Screen("search") object Filter : Screen("filter") object Product : Screen("product/{productId}") { const val ARG_PRODUCT_ID = "productId" fun createRoute(productId: String) = "product/$productId" }
// Verificación object VerifyPhone : Screen("verify_phone") object SmsVerification : Screen("sms_verification") object FaceRecognition : Screen("face_recognition") object IdVerification : Screen("id_verification") object VerifiedSuccess : Screen("verified_success") object ProfileDetail : Screen("profile_detail") object Signature : Screen("signature") object CreatePassword : Screen("create_password") object RegistrationDone : Screen("registration_done") object ProfileDetails : Screen("profile_details") }

package com.example.lendlyapp.components
import androidx.compose.foundation.Image import androidx.compose.foundation.background import androidx.compose.foundation.layout.* import androidx.compose.foundation.shape.RoundedCornerShape import androidx.compose.material3.* import androidx.compose.runtime.Composable import androidx.compose.ui.Alignment import androidx.compose.ui.Modifier import androidx.compose.ui.graphics.Color import androidx.compose.ui.layout.ContentScale import androidx.compose.ui.res.painterResource import androidx.compose.ui.text.style.TextOverflow import androidx.compose.ui.unit.dp import androidx.compose.ui.unit.sp import com.example.lendlyapp.ui.theme.interFontsSemiBold import com.example.lendlyapp.ui.theme.interFontsRegular
@Composable fun ProductCard( name: String, price: String, imageResId: Int? = null ) { Card( modifier = Modifier .width(150.dp) // Un poco más ancho para que la imagen luzca .padding(6.dp), colors = CardDefaults.cardColors(containerColor = Color.White), elevation = CardDefaults.cardElevation(defaultElevation = 2.dp), shape = RoundedCornerShape(16.dp) ) { Column( modifier = Modifier.padding(12.dp), horizontalAlignment = Alignment.CenterHorizontally ) { // Contenedor de la imagen más grande para que no se vea chiquito Box( modifier = Modifier .fillMaxWidth() .height(90.dp) .background(Color(0xFFF9F9F9), shape = RoundedCornerShape(12.dp)), contentAlignment = Alignment.Center ) { if (imageResId != null) { Image( painter = painterResource(id = imageResId), contentDescription = name, modifier = Modifier.fillMaxSize().padding(4.dp), contentScale = ContentScale.Fit ) } }
Spacer(modifier = Modifier.height(10.dp))
Column(modifier = Modifier.fillMaxWidth()) { Text( text = name, fontFamily = interFontsSemiBold, fontSize = 13.sp, maxLines = 1, overflow = TextOverflow.Ellipsis )
Text( text = price, fontFamily = interFontsRegular, fontSize = 11.sp, color = Color.Gray ) } } } }

package com.example.lendlyapp.components
import androidx.compose.foundation.Image import androidx.compose.foundation.background import androidx.compose.foundation.clickable import androidx.compose.foundation.layout.* import androidx.compose.foundation.shape.RoundedCornerShape import androidx.compose.material3.* import androidx.compose.runtime.Composable import androidx.compose.ui.Alignment import androidx.compose.ui.Modifier import androidx.compose.ui.graphics.Color import androidx.compose.ui.layout.ContentScale import androidx.compose.ui.res.painterResource import androidx.compose.ui.text.style.TextOverflow import androidx.compose.ui.unit.dp import androidx.compose.ui.unit.sp import com.example.lendlyapp.ui.theme.interFontsSemiBold import com.example.lendlyapp.ui.theme.interFontsRegular
@Composable fun ProductCard( name: String, price: String, imageResId: Int? = null, onClick: () -> Unit = {} ) { Card( modifier = Modifier .width(150.dp) // Un poco más ancho para que la imagen luzca .padding(6.dp) .clickable(onClick = onClick), colors = CardDefaults.cardColors(containerColor = Color.White), elevation = CardDefaults.cardElevation(defaultElevation = 2.dp), shape = RoundedCornerShape(16.dp) ) { Column( modifier = Modifier.padding(12.dp), horizontalAlignment = Alignment.CenterHorizontally ) { // Contenedor de la imagen más grande para que no se vea chiquito Box( modifier = Modifier .fillMaxWidth() .height(90.dp) .background(Color(0xFFF9F9F9), shape = RoundedCornerShape(12.dp)), contentAlignment = Alignment.Center ) { if (imageResId != null) { Image( painter = painterResource(id = imageResId), contentDescription = name, modifier = Modifier.fillMaxSize().padding(4.dp), contentScale = ContentScale.Fit ) } }
Spacer(modifier = Modifier.height(10.dp))
Column(modifier = Modifier.fillMaxWidth()) { Text( text = name, fontFamily = interFontsSemiBold, fontSize = 13.sp, maxLines = 1, overflow = TextOverflow.Ellipsis )
Text( text = price, fontFamily = interFontsRegular, fontSize = 11.sp, color = Color.Gray ) } } } }

package com.example.lendlyapp.pages.home

import androidx.compose.foundation.Image
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.lazy.LazyColumn
import androidx.compose.foundation.lazy.LazyRow
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.automirrored.filled.KeyboardArrowRight
import androidx.compose.material.icons.filled.Notifications
import androidx.compose.material.icons.filled.Person
import androidx.compose.material3.*
import androidx.compose.runtime.Composable
import androidx.compose.ui.Alignment
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.res.painterResource
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import com.example.lendlyapp.R
import com.example.lendlyapp.components.AccountBalanceCard
import com.example.lendlyapp.components.LoanItem
import com.example.lendlyapp.components.ProductCard
import com.example.lendlyapp.ui.theme.interFontsSemiBold
import com.example.lendlyapp.ui.theme.interFontsRegular

@Composable
fun HomeScreen(
    onNavigateToCashIn: () -> Unit
) {
    Scaffold(
        topBar = {
            HomeTopBar()
        }
    ) { innerPadding ->
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .padding(top = 8.dp)
        ) {
            // 1. Tarjeta de Saldo
            item {
                AccountBalanceCard(
                    balance = "₱ 2,500.00",
                    onCashInClick = onNavigateToCashIn
                )
            }

            // 2. Sección Unpaid Loans
            item {
                SectionHeader(title = "Unpaid Loans", onSeeAllClick = { /* TODO */ })
            }

            item {
                LoanItem(
                    companyName = "Nike Inc.",
                    amount = "₱400.00",
                    dueDate = "Fees of February",
                    logoResId = R.drawable.logo_nike // Aseguramos que sea Nike el que va arriba
                )
            }

            item {
                Spacer(modifier = Modifier.height(16.dp)) 
            }

            item {
                LoanItem(
                    companyName = "Apple Inc.",
                    amount = "₱1,500.00",
                    dueDate = "Fees of March",
                    logoResId = R.drawable.logo_apple // Aseguramos que sea Apple el que va abajo
                )
            }

            // 3. Sección Recommended For You
            item {
                SectionHeader(title = "Recommended For You", onSeeAllClick = { /* TODO */ })
            }

            item {
                LazyRow(
                    contentPadding = PaddingValues(horizontal = 10.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    item {
                        ProductCard(
                            name = "iPhone 12 Pro Max",
                            price = "₱1,200 x 24 mo",
                            imageResId = R.drawable.img_iphone
                        )
                    }
                    item {
                        ProductCard(
                            name = "Headphones",
                            price = "₱500 x 6 mo",
                            imageResId = R.drawable.img_headphones
                        )
                    }
                    item {
                        ProductCard(
                            name = "Nike Sneakers",
                            price = "₱800 x 12 mo",
                            imageResId = R.drawable.img_sneakers
                        )
                    }
                }
            }

            item {
                Spacer(modifier = Modifier.height(24.dp))
            }
        }
    }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun HomeTopBar() {
    CenterAlignedTopAppBar(
        title = {
            Image(
                painter = painterResource(id = R.drawable.icono_tres_capas), 
                contentDescription = "Lendly Logo",
                modifier = Modifier.size(width = 58.dp, height = 20.dp)
            )
        },
        navigationIcon = {
            IconButton(onClick = { /* TODO */ }) {
                Icon(
                    imageVector = Icons.Default.Person, 
                    contentDescription = "Profile",
                    modifier = Modifier.size(32.dp),
                    tint = Color.Black
                )
            }
        },
        actions = {
            IconButton(onClick = { /* TODO */ }) {
                Icon(
                    imageVector = Icons.Default.Notifications, 
                    contentDescription = "Notifications",
                    modifier = Modifier.size(32.dp),
                    tint = Color.Black
                )
            }
        },
        colors = TopAppBarDefaults.centerAlignedTopAppBarColors(
            containerColor = Color.White
        )
    )
}

@Composable
fun SectionHeader(
    title: String,
    onSeeAllClick: () -> Unit
) {
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .padding(horizontal = 16.dp, vertical = 8.dp),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Text(
            text = title,
            fontFamily = interFontsSemiBold,
            fontSize = 18.sp,
            fontWeight = FontWeight.Bold
        )
        TextButton(
            onClick = onSeeAllClick,
            contentPadding = PaddingValues(0.dp)
        ) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Text(
                    text = "See All", 
                    color = Color.Black, // Bold y Negro
                    fontSize = 14.sp,
                    fontFamily = interFontsSemiBold,
                    fontWeight = FontWeight.Bold
                )
                Spacer(modifier = Modifier.width(4.dp))
                Icon(
                    imageVector = Icons.AutoMirrored.Filled.KeyboardArrowRight,
                    contentDescription = null,
                    modifier = Modifier.size(16.dp),
                    tint = Color.Black // Negro para combinar con el texto bold
                )
            }
        }
    }
}

