import com.example.lendlyapp.components.LoanItem
import com.example.lendlyapp.components.ProductCard
import com.example.lendlyapp.ui.theme.interFontsSemiBold

@Composable
fun HomeScreen(
    onNavigateToCashIn: () -> Unit,
    onNavigateToProduct: (String) -> Unit = {}
) {
    val navigateToProduct = onNavigateToProduct
    Scaffold(
        topBar = {
            HomeTopBar()
        }
    ) { innerPadding ->
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding)
                .padding(top = 8.dp)
        ) {
            // 1. Tarjeta de Saldo
            item {
                AccountBalanceCard(
                    balance = "₱ 2,500.00",
                    onCashInClick = onNavigateToCashIn
                )
            }

            // 2. Sección Unpaid Loans
            item {
                SectionHeader(title = "Unpaid Loans", onSeeAllClick = { /* TODO */ })
            }

            item {
                LoanItem(
                    companyName = "Nike Inc.",
                    amount = "₱400.00",
                    dueDate = "Fees of February",
                    logoResId = R.drawable.logo_nike // Aseguramos que sea Nike el que va arriba
                )
            }

            item {
                Spacer(modifier = Modifier.height(16.dp)) 
            }

            item {
                LoanItem(
                    companyName = "Apple Inc.",
                    amount = "₱1,500.00",
                    dueDate = "Fees of March",
                    logoResId = R.drawable.logo_apple // Aseguramos que sea Apple el que va abajo
                )
            }

            // 3. Sección Recommended For You
            item {
                SectionHeader(title = "Recommended For You", onSeeAllClick = { /* TODO */ })
            }

            item {
                LazyRow(
                    contentPadding = PaddingValues(horizontal = 10.dp),
                    modifier = Modifier.fillMaxWidth()
                ) {
                    item {
                        ProductCard(
                            name = "iPhone 12 Pro Max",
                            price = "₱1,200 x 24 mo",
                            imageResId = R.drawable.img_iphone,
                            onClick = { navigateToProduct("iphone") }
                        )
                    }
                    item {
                        ProductCard(
                            name = "Headphones",
                            price = "₱500 x 6 mo",
                            imageResId = R.drawable.img_headphones,
                            onClick = { navigateToProduct("headphones") }
                        )
                    }
                    item {
                        ProductCard(
                            name = "Nike Sneakers",
                            price = "₱800 x 12 mo",
                            imageResId = R.drawable.img_sneakers,
                            onClick = { navigateToProduct("sneakers") }
                        )
                    }
                }
            }

            item {
                Spacer(modifier = Modifier.height(24.dp))
            }
        }
    }
}

